/* Generated by Trae Work */
(function () {
  const ACCESS_CODE = "ELIMINATE";
  const KEY = "eliminator_auth";

  function setMsg(el, text, type) {
    if (!el) return;
    el.textContent = text || "";
    el.classList.remove("ok", "error");
    if (type) el.classList.add(type);
  }

  // Always require the access code when the login page is opened.
  // This prevents an old browser session from silently bypassing the form.
  sessionStorage.removeItem(KEY);

  const form = document.getElementById("login-form");
  const input = document.getElementById("access");
  const msg = document.getElementById("login-msg");

  if (!form || !input) return;

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const value = String(input.value || "").trim();
    if (!value) return setMsg(msg, "Please enter the access code.", "error");
    if (value !== ACCESS_CODE) return setMsg(msg, "Wrong code. Try again.", "error");

    sessionStorage.setItem(KEY, "1");
    setMsg(msg, "Access granted. Redirecting…", "ok");
    setTimeout(() => window.location.replace("./app.html"), 350);
  });
})();

